cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace nvcuda;

// WMMA tile sizes (must be 16 for tensor cores)
#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 16

// Block tile size (multiple of WMMA tile)
#define BLOCK_M 32   // 2 WMMA rows per block
#define BLOCK_N 32   // 2 WMMA cols per block

// One block = 4 warps = 128 threads
#define THREADS_PER_BLOCK 128

// ---------------------------------------------------------------------------
// Kernel: batched FP16 matrix multiplication using Tensor Cores (WMMA)
// ---------------------------------------------------------------------------
__global__ void bmm_wmma_kernel(const __half* __restrict__ A,
                                 const __half* __restrict__ B,
                                 __half* __restrict__ C,
                                 int batch,
                                 int M,
                                 int N,
                                 int K) {
    // ----- block / warp coordinates -----
    int batch_idx = blockIdx.z;
    int block_row = blockIdx.y * BLOCK_M;   // top‑left row of the block tile in C
    int block_col = blockIdx.x * BLOCK_N;   // top‑left col of the block tile in C

    // each warp computes one WMMA tile (16×16)
    int warp_id   = threadIdx.x / 32;               // 0..3 within the block
    int warp_row  = (warp_id / (BLOCK_N / WMMA_N)) * WMMA_M; // 0 or 16
    int warp_col  = (warp_id % (BLOCK_N / WMMA_N)) * WMMA_N; // 0 or 16

    // starting coordinates of this warp's output tile
    int c_row = block_row + warp_row;
    int c_col = block_col + warp_col;

    // pointers to the beginning of this batch
    const __half* A_batch = A + batch_idx * (size_t)M * K;
    const __half* B_batch = B + batch_idx * (size_t)K * N;
    __half*       C_batch = C + batch_idx * (size_t)M * N;

    // accumulator fragment (FP32)
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> acc_frag;
    wmma::fill_fragment(acc_frag, 0.0f);

    // loop over K dimension in WMMA_K sized steps
    for (int k = 0; k < K; k += WMMA_K) {
        // ---- load A tile (row‑major) ----
        wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K,
                       __half, wmma::row_major> a_frag;
        const __half* a_tile_ptr = A_batch + (size_t)c_row * K + (k);
        wmma::load_matrix_sync(a_frag, a_tile_ptr, K);

        // ---- load B tile (col‑major) ----
        wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K,
                       __half, wmma::col_major> b_frag;
        const __half* b_tile_ptr = B_batch + (size_t)k * N + (c_col);
        wmma::load_matrix_sync(b_frag, b_tile_ptr, N);

        // ---- matrix multiply‑accumulate ----
        wmma::mma_sync(acc_frag, a_frag, b_frag, acc_frag);
    }

    // ---- store result back to C (row‑major) ----
    __half* c_tile_ptr = C_batch + (size_t)c_row * N + c_col;
    wmma::store_matrix_sync(c_tile_ptr, acc_frag, N, wmma::mem_row_major);
}

// ---------------------------------------------------------------------------
// PyTorch binding
// ---------------------------------------------------------------------------
torch::Tensor bmm_fp16_wmma(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat16 && B.dtype() == torch::kFloat16,
                "inputs must be float16");
    TORCH_CHECK(A.dim() == 3 && B.dim() == 3,
                "inputs must be 3‑D tensors");
    TORCH_CHECK(A.size(0) == B.size(0),
                "batch dimensions must match");
    TORCH_CHECK(A.size(2) == B.size(1),
                "inner dimensions must match");

    const int batch = A.size(0);
    const int M = A.size(1);
    const int K = A.size(2);
    const int N = B.size(2);

    auto C = torch::empty({batch, M, N}, A.options());

    dim3 block(THREADS_PER_BLOCK);
    dim3 grid( (N + BLOCK_N - 1) / BLOCK_N,
               (M + BLOCK_M - 1) / BLOCK_M,
               batch );

    bmm_wmma_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(A.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(B.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(C.data_ptr<at::Half>()),
        batch, M, N, K);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
    return C;
}
"""

cpp_source = "torch::Tensor bmm_fp16_wmma(torch::Tensor A, torch::Tensor B);"

bmm_ext = load_inline(
    name="bmm_fp16_wmma_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["bmm_fp16_wmma"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._bmm = bmm_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        if A.dtype != torch.float16:
            A = A.half()
        if B.dtype != torch.float16:
            B = B.half()
        return self._bmm.bmm_fp16_wmma(A, B)
